import type { Metadata } from "next";

import { hasPermission, requirePagePermission } from "@/lib/auth/session";
import { listNotifications } from "@/lib/queries/catalog";
import { NotificationList } from "./notification-list";

export const metadata: Metadata = {
  title: "Notifikasi",
};

/**
 * Alert centre.
 *
 * The rows are generated on request by the list component rather than being
 * stored stale: stock conditions change with every sale, purchase, and
 * adjustment, and a notification centre that has to be regenerated by hand would
 * be quietly wrong within minutes.
 */
export default async function NotificationsPage() {
  const user = await requirePagePermission("notifications:view");

  const [notifications, canManage] = await Promise.all([
    listNotifications({ userId: user.id, take: 100 }),
    hasPermission("notifications:manage"),
  ]);

  const unread = notifications.filter((entry) => !entry.isRead).length;

  return (
    <div className="space-y-4">
      <div>
        <h1 className="text-lg font-semibold tracking-tight">Notifikasi</h1>
        <p className="text-sm text-muted-foreground">
          Peringatan stok menipis, barang habis, dan barang mendekati
          kedaluwarsa.
          {unread > 0 ? (
            <>
              {" "}
              <span className="font-medium text-foreground">
                {unread} belum dibaca.
              </span>
            </>
          ) : null}
        </p>
      </div>

      <NotificationList notifications={notifications} canManage={canManage} />

      <p className="text-xs text-muted-foreground">
        Peringatan stok dihitung ulang dari data terkini setiap kali halaman ini
        dibuka, jadi tidak perlu ada tombol yang harus ditekan secara berkala.
      </p>
    </div>
  );
}